<?php
declare(strict_types=1);
namespace Plati;
if(!defined('PLATI_ENTRY')&&PHP_SAPI!=='cli'){http_response_code(404);exit;}

final class Review {
 static function prepare(\PDO $db,array $input,array $actor):array {
  permit($actor,'operate');$kind=$input['kind']??'';$action=$input['action']??'';$reason=trim((string)($input['reason']??''));if(mb_strlen($reason)<10||mb_strlen($reason)>1000)throw new Problem('Completează motivul cu 10–1000 caractere.');if(!in_array($kind,['netopia','fan','site'],true)||!in_array($action,['confirmed','rejected','deferred','closed_user_reported','refunded_user_reported'],true))throw new Problem('Acțiune invalidă.');if($kind!=='netopia'&&in_array($action,['closed_user_reported','refunded_user_reported'],true))throw new Problem('Închiderea fără factură se aplică numai plăților NETOPIA.');
  $r=one($db,'SELECT * FROM '.Store::TABLE[$kind].' WHERE id=? FOR UPDATE',[(int)($input['resource']??0)]);if(!$r||!hash_equals($r['source_hash'],(string)($input['resource_hash']??'')))throw new Problem('Sursa s-a schimbat. Reîncarcă verificarea.',409);
  $i=null;if(in_array($action,['confirmed','rejected'],true)){$i=one($db,"SELECT * FROM invoices WHERE id=? AND scope<>'internal' AND amount_cents>0 FOR UPDATE",[(int)($input['invoice']??0)]);if(!$i||!hash_equals($i['source_hash'],(string)($input['invoice_hash']??'')))throw new Problem('Factura s-a schimbat sau nu este eligibilă.',409);}
  if($action!=='rejected'&&$action!=='deferred'){$table=['netopia'=>'payment_resolutions','fan'=>'shipment_assignments','site'=>'invoice_orders'][$kind];$col=['netopia'=>'payment_id','fan'=>'shipment_id','site'=>'order_id'][$kind];if(one($db,'SELECT * FROM '.$table.' WHERE '.$col.'=? FOR UPDATE',[$r['id']]))throw new Problem('Resursa este deja asociată sau închisă. Verifică istoricul.',409);}
  if($kind==='netopia'&&one($db,"SELECT id FROM decisions WHERE payment_id=? AND action IN ('netopia_topup','netopia_return_review','netopia_return_partial_review') AND active=1",[$r['id']]))throw new Problem('Plata este deja atribuită sau păstrată la retururi pentru verificare.',409);
  if($kind!=='site'&&$i&&Allocations::rows($db,(int)$i['id']))throw new Problem('Factura are deja o repartizare NETOPIA confirmată.',409);
  $diff=null;if($action==='confirmed'){if(one($db,"SELECT id FROM cash_circuits WHERE original_invoice_id=? AND status='confirmed' FOR UPDATE",[$i['id']])
     && ($kind!=='site'||!Matching::cashOrderCompatible($i,$r)))throw new Problem('Factura are un circuit GPD numerar confirmat; verifică această contradicție.',409);if(one($db,"SELECT id FROM decisions WHERE action='revoked' AND active=1 AND ".['netopia'=>'payment_id','fan'=>'shipment_id','site'=>'order_id'][$kind].'=? FOR UPDATE',[$r['id']]))throw new Problem('Resursa este blocată după revocare; administratorul trebuie să o reconsidere.',409);if((int)$i['balance_cents']<0)throw new Problem('Factura are sold negativ și este exclusă.');$column=['netopia'=>'payment_id','fan'=>'shipment_id','site'=>'order_id'][$kind];if(one($db,'SELECT id FROM decisions WHERE action=\'rejected\' AND active=1 AND invoice_id=? AND '.$column.'=? FOR UPDATE',[$i['id'],$r['id']]))throw new Problem('Această pereche a fost respinsă. Este necesară reconsiderare explicită.');$currentTable=['netopia'=>'payment_resolutions','fan'=>'shipment_assignments','site'=>'invoice_orders'][$kind];if(one($db,'SELECT * FROM '.$currentTable.' WHERE invoice_id=? FOR UPDATE',[$i['id']]))throw new Problem('Factura are deja o legătură de acest tip; nu se înlocuiește automat.',409);
   $amount=$r[$kind==='netopia'?'gross_amount_cents':($kind==='fan'?'cash_due_cents':'amount_cents')];$trackingOnly=$kind==='fan'&&method($r)==='NETOPIA'&&($amount===null||(int)$amount===0);$diff=$trackingOnly?null:(int)$amount-(int)$i['amount_cents'];if($diff!==null&&$diff!==0&&($input['accept_difference']??false)!==true)throw new Problem('Confirmă explicit diferența de sumă: '.number_format($diff/100,2,',','.').' lei.');
   if($kind==='netopia'&&one($db,'SELECT s.id FROM shipment_assignments a JOIN fan_shipments s ON s.id=a.shipment_id WHERE a.invoice_id=? AND s.cash_due_cents>0 FOR UPDATE',[$i['id']]))throw new Problem('Există ramburs FAN pozitiv pe factură; conflictul trebuie lămurit.');if($kind==='fan'&&(int)($r['cash_due_cents']??0)>0&&one($db,'SELECT payment_id FROM payment_resolutions WHERE invoice_id=? FOR UPDATE',[$i['id']]))throw new Problem('Există o plată NETOPIA; rambursul FAN pozitiv este contradictoriu.');
  }
  return ['input'=>$input,'kind'=>$kind,'action'=>$action,'reason'=>$reason,'resource'=>$r,'invoice'=>$i,'difference'=>$diff];
 }
 static function save(\PDO $db,array $input,array $actor):array {
  return transaction($db,function()use($db,$input,$actor){$request=(string)($input['request_key']??'');if(strlen($request)<12||strlen($request)>200)throw new Problem('Cheie de salvare invalidă.');$key='user:'.$actor['id'].':'.hash('sha256',$request);permit($actor,'operate');$kind=$input['kind']??'';if(!isset(Store::TABLE[$kind])||$kind==='omc')throw new Problem('Tip invalid.');query($db,'SELECT id FROM '.Store::TABLE[$kind].' WHERE id=? FOR UPDATE',[(int)($input['resource']??0)]);$intent=$input;unset($intent['request_key'],$intent['batch_revision']);$intentHash=hashSource($intent);$old=one($db,'SELECT id,action,source_hashes_json FROM decisions WHERE idempotency_key=?',[$key]);if($old){$proof=json_decode($old['source_hashes_json'],true);if(isset($proof['request_hash'])&&!hash_equals($proof['request_hash'],$intentHash))throw new Problem('Aceeași cheie de salvare a fost reutilizată pentru altă decizie.',409);return ['saved'=>true,'decision'=>(int)$old['id'],'repeated'=>true];}$v=self::prepare($db,$input,$actor);$r=$v['resource'];$i=$v['invoice'];$kind=$v['kind'];$targets=['invoice'=>$i['id']??null,match($kind){'fan'=>'shipment','site'=>'order',default=>'payment'}=>(int)$r['id']];$proof=['request_hash'=>$intentHash,'resource_hash'=>$r['source_hash'],'invoice_hash'=>$i['source_hash']??null,'source_amount_cents'=>$r[$kind==='fan'?'cash_due_cents':($kind==='netopia'?'gross_amount_cents':'amount_cents')],'invoice_amount_cents'=>$i['amount_cents']??null];$id=decision($db,$v['action'],$targets,$proof,$v['reason'],$actor,$key,$v['difference']);
   if($v['action']==='confirmed'){if($kind==='netopia')query($db,'INSERT INTO payment_resolutions(payment_id,invoice_id,resolution,decision_id) VALUES(?,?,?,?)',[$r['id'],$i['id'],(int)$i['balance_cents']>0?'associated':'historical',$id]);elseif($kind==='fan')query($db,'INSERT INTO shipment_assignments(shipment_id,invoice_id,primary_slot,assignment_status,decision_id) VALUES(?,?,1,?,?)',[$r['id'],$i['id'],(int)$i['balance_cents']>0?'associated':'historical',$id]);else query($db,'INSERT INTO invoice_orders(invoice_id,order_id,document_role,decision_id) VALUES(?,?,\'original\',?)',[$i['id'],$r['id'],$id]);if($i['scope']!=='accepted')query($db,"UPDATE invoices SET scope='accepted',scope_reason='manual' WHERE id=?",[$i['id']]);}
   elseif(in_array($v['action'],['closed_user_reported','refunded_user_reported'],true))query($db,'INSERT INTO payment_resolutions(payment_id,invoice_id,resolution,decision_id) VALUES(?,NULL,?,?)',[$r['id'],$v['action'],$id]);audit($db,'decision_saved',['action'=>$v['action'],'targets'=>$targets,'difference_cents'=>$v['difference']],$actor,$id);return ['saved'=>true,'decision'=>$id,'difference_cents'=>$v['difference']];});
 }
 static function candidates(\PDO $db,string $kind,int $resource,string $search='',string $days='all'):array {if(!in_array($kind,['netopia','fan','site'],true))throw new Problem('Tip invalid.');$r=one($db,'SELECT * FROM '.Store::TABLE[$kind].' WHERE id=?',[$resource]);if(!$r)throw new Problem('Sursa nu există.',404);$amount=$r[$kind==='fan'?'cash_due_cents':($kind==='netopia'?'gross_amount_cents':'amount_cents')];$date=$r[$kind==='fan'?'awb_date':($kind==='netopia'?'operation_date':'order_date')];$where="i.scope<>'internal' AND i.amount_cents>0 AND i.balance_cents>=0";$args=[];$orderingName=nameKey($r['recipient']??$r['client']??'');if($search!==''){$where.=' AND (LOWER(i.invoice_number) LIKE LOWER(?) OR LOWER(i.client) LIKE LOWER(?))';$args=['%'.$search.'%','%'.$search.'%'];}elseif($amount!==null&&(int)$amount>0){$where.=' AND ABS(i.amount_cents-?)<=1';$args[]=(int)$amount;}else{$where.=' AND i.name_hash=?';$args[]=hash('sha256',nameKey($r['recipient']??$r['client']??''));}if($days!=='all'){if(!ctype_digit($days)||(int)$days>3650)throw new Problem('Interval invalid.');if($date){$where.=' AND i.invoice_date BETWEEN ? AND ?';$d=new \DateTimeImmutable($date);$args[]=$d->modify('-'.$days.' days')->format('Y-m-d');$args[]=$d->modify('+'.$days.' days')->format('Y-m-d');}}
  $rows=query($db,'SELECT i.id,i.invoice_number,i.invoice_date,i.client,i.amount_cents,i.balance_cents,i.scope,i.source_hash,COALESCE(p.payment_id,(SELECT allocation_occupied.payment_id FROM decisions allocation_occupied WHERE allocation_occupied.invoice_id=i.id AND allocation_occupied.action=\'netopia_allocation\' AND allocation_occupied.active=1 LIMIT 1)) AS occupied_payment,s.shipment_id AS occupied_shipment,o.order_id AS occupied_order FROM invoices i LEFT JOIN payment_resolutions p ON p.invoice_id=i.id LEFT JOIN shipment_assignments s ON s.invoice_id=i.id LEFT JOIN invoice_orders o ON o.invoice_id=i.id WHERE '.$where.' ORDER BY CASE WHEN i.normalized_name=? THEN 0 ELSE 1 END,ABS(i.amount_cents-?),COALESCE(ABS(DATEDIFF(i.invoice_date,?)),999999),i.id LIMIT 100',[...$args,$orderingName,(int)($amount??0),$date])->fetchAll();foreach($rows as &$i){$i['difference_cents']=$amount===null?null:(int)$amount-(int)$i['amount_cents'];$i['date_gap']=$date&&$i['invoice_date']?gap($date,$i['invoice_date']):null;}unset($i);$resolution=$kind==='netopia'?one($db,'SELECT * FROM '.Topups::links().' l WHERE payment_id=?',[$resource]):($kind==='fan'?one($db,'SELECT * FROM shipment_assignments WHERE shipment_id=?',[$resource]):one($db,'SELECT * FROM invoice_orders WHERE order_id=?',[$resource]));return ['partial_return'=>$kind==='netopia'?ReturnReview::pending($db,(int)$r['id']):null,'payment_allocations'=>$kind==='netopia'?Allocations::paymentRows($db,(int)$r['id']):[],'resource'=>$r,'site_order'=>$kind==='netopia'?one($db,'SELECT order_number,amount_cents FROM site_orders WHERE order_number=?',[$r['canonical_external_id']]):null,'invoice_paid_cents'=>$resolution&&$kind==='netopia'?(int)query($db,'SELECT COALESCE(SUM(p.gross_amount_cents),0) FROM '.Topups::links().' l JOIN netopia_payments p ON p.id=l.payment_id WHERE l.invoice_id=?',[$resolution['invoice_id']])->fetchColumn():null,'kind'=>$kind,'resolution'=>$resolution,'invoices'=>$rows,'limit'=>100];
 }
 static function batch(\PDO $db,array $user):array{$b=one($db,"SELECT * FROM review_batches WHERE actor_id=? AND status='draft' ORDER BY id DESC LIMIT 1",[$user['id']]);if(!$b)return ['id'=>null,'revision'=>0,'items'=>[]];return ['id'=>(int)$b['id'],'revision'=>(int)$b['revision'],'items'=>array_map(fn($r)=>json_decode($r['proposal_json'],true),query($db,'SELECT proposal_json FROM review_items WHERE batch_id=? ORDER BY id',[$b['id']])->fetchAll())];}
 static function stage(\PDO $db,array $input,array $user):array{return transaction($db,function()use($db,$input,$user){query($db,'SELECT id FROM users WHERE id=? FOR UPDATE',[$user['id']]);self::prepare($db,$input,$user);$b=self::batch($db,$user);if($b['revision']!==(int)($input['batch_revision']??-1))throw new Problem('Lotul s-a schimbat. Reîncarcă.',409);if($b['id'])query($db,'SELECT id FROM review_batches WHERE id=? FOR UPDATE',[$b['id']]);if(count($b['items'])>=200)throw new Problem('Maximum 200 decizii per lot.');foreach($b['items'] as $old)if($old['kind']===$input['kind']&&(($old['resource']===$input['resource']&&($old['action']!=='rejected'||$input['action']!=='rejected'))||($old['action']==='confirmed'&&$input['action']==='confirmed'&&$old['invoice']===$input['invoice'])))throw new Problem('Plata sau factura este deja selectată în lot.');if(!$b['id']){query($db,"INSERT INTO review_batches(actor_id,status,revision,result_json) VALUES(?,'draft',0,'{}')",[$user['id']]);$b['id']=(int)$db->lastInsertId();}$key=hash('sha256',json([$input['kind'],$input['resource'],$input['action'],$input['invoice']??null]));query($db,'INSERT INTO review_items(batch_id,item_key,proposal_json) VALUES(?,?,?)',[$b['id'],$key,json($input)]);$q=query($db,'UPDATE review_batches SET revision=revision+1 WHERE id=? AND revision=?',[$b['id'],$b['revision']]);if(!$q->rowCount())throw new Problem('Lot schimbat între timp.',409);return self::batch($db,$user);});}
 static function commitBatch(\PDO $db,array $input,array $user):array{return transaction($db,function()use($db,$input,$user){$b=one($db,'SELECT * FROM review_batches WHERE id=? AND actor_id=? FOR UPDATE',[(int)$input['id'],$user['id']]);if(!$b)throw new Problem('Lot inexistent.');if($b['status']==='committed')return json_decode($b['result_json'],true);if($b['status']!=='draft'||(int)$b['revision']!==(int)$input['revision'])throw new Problem('Lotul s-a schimbat.',409);$items=query($db,'SELECT proposal_json FROM review_items WHERE batch_id=? ORDER BY id',[$b['id']])->fetchAll();if(!$items)throw new Problem('Lot gol.');$saved=[];foreach($items as $item)$saved[]=self::save($db,json_decode($item['proposal_json'],true),$user);$result=['saved'=>count($saved),'decisions'=>$saved];query($db,"UPDATE review_batches SET status='committed',result_json=? WHERE id=?",[json($result),$b['id']]);return $result;});}
 static function removeItem(\PDO $db,array $input,array $user):array{return transaction($db,function()use($db,$input,$user){query($db,'SELECT id FROM users WHERE id=? FOR UPDATE',[$user['id']]);$b=self::batch($db,$user);if(!$b['id']||$b['revision']!==(int)$input['revision'])throw new Problem('Lotul s-a schimbat.',409);$q=query($db,'DELETE FROM review_items WHERE batch_id=? AND item_key=?',[$b['id'],hash('sha256',json([$input['kind'],(int)$input['resource'],$input['action'],isset($input['invoice'])?(int)$input['invoice']:null]))]);if(!$q->rowCount())throw new Problem('Selecția nu mai există.',409);query($db,'UPDATE review_batches SET revision=revision+1 WHERE id=?',[$b['id']]);return self::batch($db,$user);});}
 static function approveAlias(\PDO $db,array $input,array $user):array{permit($user,'operate');return transaction($db,function()use($db,$input,$user){$a=one($db,"SELECT * FROM payment_identifiers WHERE provider='NETOPIA' AND external_id=? AND status='pending' FOR UPDATE",[(string)$input['external_id']]);if(!$a)throw new Problem('Identificatorul nu mai este în așteptare.');$proof=json_decode($a['proof_json'],true);$r=$proof['candidate'];$p=one($db,'SELECT * FROM netopia_payments WHERE id=? FOR UPDATE',[$a['payment_id']]);if(!hash_equals($p['source_hash'],(string)$input['resource_hash']))throw new Problem('Plata s-a schimbat.',409);$same=(int)$p['gross_amount_cents']===$r['gross_amount_cents']&&$p['operation_date']===$r['operation_date']&&$p['transfer_date']===$r['transfer_date']&&$p['operation_number']===$r['operation_number']&&$p['normalized_name']===nameKey($r['client']);if(!$same)throw new Problem('Datele financiare nu sunt identice; necesită investigare.');query($db,"UPDATE payment_identifiers SET status='approved' WHERE provider='NETOPIA' AND external_id=?",[$input['external_id']]);Store::upsert($db,'netopia',$r,(int)$proof['import_row'],$user);audit($db,'identifier_alias_approved',['alias'=>$input['external_id'],'canonical'=>$p['canonical_external_id']],$user);return ['saved'=>true];});}
}
